    wp = dgebid("PHOTO_OPT").value;
    vp = dgebid("VIEW_OPT").value;
    if(trim(searchtype)=="lpd"){
      if(contact=="Y")
        dgebid("CONTACT_OPT").value = cp = (cp=='Y')?'N':'Y';
      if(shortlist=="Y")
        dgebid("PHOTO_OPT").value = wp = (wp=='Y')?'N':'Y';
      if(viewed=="Y")
        dgebid("VIEW_OPT").value = vp = (wp=='Y')?'N':'Y';

      lpdparameters ='&wp='+wp+'&vp='+vp+'&cp='+cp+'&randid='+document.getElementById("randid");
    }else{
      if(contact=="Y")
        dgebid("CONTACT_OPT").value=(dgebid("CONTACT_OPT").value=='Y')?'N':'Y';
      if(shortlist=="Y")
        dgebid("PHOTO_OPT").value=(dgebid("PHOTO_OPT").value=='Y')?'N':'Y';
      if(viewed=="Y")
        dgebid("VIEW_OPT").value=(dgebid("VIEW_OPT").value=="Y")?'N':'Y';
      if(ignore=="Y")
        dgebid("Premium").value=(dgebid("Premium").value=='Y')?'N':'Y';
    }
    if(searchtype!="lpd"){
      //alert(dgebid("VIEW_OPT").value);
      document.cookie = Jsg_c_name+"=;path=/search/";
      document.srchmore.method = "post";
      dgebid('facet').value="Y";
      dgebid('showclearall').value="Y";
      document.srchmore.action="searchres_ql.php?facetqrystr=dontshow";
      document.srchmore.submit();
